toolArgs.file_text:
/* ── Layout shell ── */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #1d1c1d;
    background: #fff;
}

/* ── Channel sidebar (≈20%) ── */
.channel-sidebar {
    width: 260px;
    min-width: 200px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 18px 16px 10px;
    border-bottom: 1px solid rgba(255,255,255,.1);
}

.sidebar-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 6px;
    margin: 0 8px;
    transition: background .12s;
}

.channel-item:hover {
    background: rgba(255,255,255,.08);
}

.channel-item.active {
    background: #1264a3;
    color: #fff;
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-weight: 600;
    font-size: .9rem;
}

.unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: .7rem;
    font-weight: 700;
    padding: 1px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

.channel-desc {
    display: block;
    font-size: .75rem;
    opacity: .7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 1px;
}

/* ── Main message area ── */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    border-right: 1px solid #e8e8e8;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.message-header h3 {
    margin: 0;
    font-size: 1.05rem;
}

.header-desc {
    font-size: .82rem;
    color: #616061;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #888;
    font-size: .82rem;
}

.empty-state {
    margin: auto;
    color: #888;
    font-size: 1rem;
}

/* ── Message card ── */
.message-card {
    position: relative;
    padding: 6px 8px;
    border-radius: 6px;
    margin-bottom: 2px;
    transition: background .1s;
}

.message-card:hover {
    background: #f8f8f8;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.msg-author {
    font-size: .9rem;
}

.msg-time {
    font-size: .75rem;
    color: #888;
}

.msg-content {
    font-size: .9rem;
    line-height: 1.45;
    margin: 2px 0 4px;
    white-space: pre-wrap;
    word-break: break-word;
}

/* ── Reactions ── */
.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 2px;
}

.reaction-badge {
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    padding: 1px 8px;
    font-size: .8rem;
    cursor: pointer;
    transition: background .1s;
}

.reaction-badge:hover {
    background: #e0e7ff;
    border-color: #93a3f8;
}

/* ── Thread link ── */
.thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: .8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Hover action buttons ── */
.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 1px 4px rgba(0,0,0,.08);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: .8rem;
    padding: 3px 6px;
    border-radius: 4px;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
}

/* ── Emoji picker ── */
.emoji-picker-wrapper {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 2px;
    box-shadow: 0 4px 12px rgba(0,0,0,.12);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* ── Compose area ── */
.compose-area {
    display: flex;
    gap: 8px;
    padding: 10px 20px 14px;
    border-top: 1px solid #e8e8e8;
    flex-shrink: 0;
    background: #fff;
}

.compose-input {
    flex: 1;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 10px;
    font-size: .9rem;
    resize: none;
    font-family: inherit;
    outline: none;
    transition: border-color .15s;
}

.compose-input:focus {
    border-color: #1264a3;
}

.send-btn {
    padding: 8px 18px;
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    font-size: .85rem;
    cursor: pointer;
    align-self: flex-end;
    transition: background .12s;
}

.send-btn:hover:not(:disabled) {
    background: #005e44;
}

.send-btn:disabled {
    opacity: .45;
    cursor: default;
}

/* ── Thread panel (≈25%) ── */
.thread-panel {
    width: 340px;
    min-width: 280px;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #e8e8e8;
    background: #fff;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 2px 6px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #f0f0f0;
    color: #1d1c1d;
}

